//! Phase B — full-pipeline differential tests for `long_exec` (`CONFIGS.md`
//! rows 20-33, 35 and `ERRORS.md` rows 1-7, 15, 18-20).
//!
//! `long_exec` is the one-shot wrapper: `srand(seed)` → fill 262144 slots with
//! `rand()` → 2000 × `perform_expensive_operations()` → XOR-reduce →
//! `printf("%d\n", …)`.  That is 5.24e10 kernel applications, ~8 minutes per call
//! in the C library, so this file has two layers:
//!
//! * **fast layer** (runs by default): the Rust `.so` is driven live for the
//!   whole `CONFIGS.md` seed sweep and its `printf` bytes are compared against
//!   stdout recorded from *the C `.so` under test* (`tests/cref/`, regenerated by
//!   `tools/gen_c_refs.sh`).
//! * **live layer** (`#[ignore]`, ~8-25 min each): both `.so`s are loaded in one
//!   process and `long_exec` is called on each, comparing the captured `printf`
//!   bytes *and* all 1 MiB of the resulting exported `array`.  Run with
//!   `cargo test --test long_exec_diff -- --ignored`; select seeds with
//!   `LONG_SEEDS=7,255`.

mod common;

use common::{assert_arrays_eq, capture_stdout, load_pair};

fn seeds_from_env(default: &str) -> Vec<u32> {
    std::env::var("LONG_SEEDS")
        .unwrap_or_else(|_| default.to_string())
        .split(',')
        .filter(|s| !s.trim().is_empty())
        .map(|s| s.trim().parse::<u32>().expect("LONG_SEEDS must be u32 values"))
        .collect()
}

/// Rows 20-30: the whole recorded seed sweep, Rust `.so` vs C `.so` output.
#[test]
fn rows20_30_seed_sweep_against_recorded_c_output() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let refs = common::load_c_references();
    assert!(
        refs.len() >= 30,
        "expected the recorded C seed sweep in {} -- found {} files; run tools/gen_c_refs.sh",
        common::c_reference_dir().display(),
        refs.len()
    );

    // Every configuration axis value called out in CONFIGS.md rows 20-30 must be
    // present in the recorded sweep, so the table cannot silently lose coverage.
    for required in [
        0u32, 1, 7, 255, 65535, 65536, 8191, 8192, 8193, 2147483647, 2147483648, 2147483649,
        4294967294, 4294967295,
    ] {
        assert!(
            refs.contains_key(&required),
            "CONFIGS.md requires seed {required} but tests/cref has no recording for it"
        );
    }

    let p = load_pair();
    let mut checked = 0usize;
    for (&seed, want) in refs.iter() {
        let got = capture_stdout(&format!("sweep{seed}"), || p.r.long_exec(seed));
        let text = String::from_utf8(got).expect("stdout must be ASCII");
        assert_eq!(
            text,
            format!("{want}\n"),
            "seed {seed}: Rust .so printed {:?}, C .so printed {:?}",
            text,
            format!("{want}\n")
        );
        checked += 1;
    }
    assert_eq!(checked, refs.len());
    eprintln!("rows20-30: {checked} seeds matched the C .so byte-for-byte");
}

/// Row 21: glibc `srand(0)` aliases `srand(1)`, so both seeds must print the same.
#[test]
fn row21_srand_zero_aliases_srand_one() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let p = load_pair();
    let a = capture_stdout("alias0", || p.r.long_exec(0));
    let b = capture_stdout("alias1", || p.r.long_exec(1));
    assert_eq!(a, b, "seed 0 and seed 1 must produce identical output");
    let refs = common::load_c_references();
    assert_eq!(refs[&0], refs[&1], "the C .so must also alias them");
    assert_eq!(String::from_utf8_lossy(&a).trim_end(), refs[&0]);
}

/// Rows 31-32: residual `array` state and PRNG re-seeding across repeated
/// `long_exec` calls in ONE library instance.  Each call's output must equal the
/// fresh-process C recording for that seed.
#[test]
fn rows31_32_ordering_and_idempotence_in_one_instance() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let refs = common::load_c_references();
    let p = load_pair();
    // seed 7, then 255, then 7 again -- run 3 must reproduce run 1 exactly.
    let script = [7u32, 255, 7, 0, 1, 4294967295, 7];
    let mut outs = Vec::new();
    for &s in &script {
        let got = capture_stdout(&format!("seq{s}"), || p.r.long_exec(s));
        let text = String::from_utf8(got).expect("ASCII");
        assert_eq!(
            text,
            format!("{}\n", refs[&s]),
            "run of seed {s} inside a sequence diverged from the fresh-process C output"
        );
        outs.push(text);
    }
    assert_eq!(outs[0], outs[2], "row32: repeating seed 7 must be idempotent");
    assert_eq!(outs[0], outs[6], "row32: seed 7 after four other runs");
    assert_eq!(outs[3], outs[4], "row31: seeds 0/1 inside a sequence");
}

/// Row 33: mix the two entry points -- feed `long_exec`'s `f^200000` output back
/// through `perform_expensive_operations()`.  The C side is affordable here
/// because only the *second* stage is re-run: the first stage's C output is the
/// recorded array dump if present, otherwise this row is covered live by
/// `row33_live_mixed_entry_points`.
#[test]
fn row33_mixed_entry_points_via_recorded_array_dump() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let dumps = common::load_c_array_dumps();
    assert!(
        !dumps.is_empty(),
        "expected at least one recorded C array dump in {}",
        common::c_reference_dir().display()
    );
    let p = load_pair();
    for (seed, c_after_long_exec) in dumps {
        // Stage 1: Rust `long_exec` must land on the identical 1 MiB array.
        let _ = capture_stdout(&format!("mix{seed}"), || p.r.long_exec(seed));
        assert_arrays_eq(
            &format!("row33 seed {seed}: array after long_exec"),
            &c_after_long_exec,
            p.r.array(),
        );
        // Stage 2: feed that residual state back through the low-level entry
        // point in BOTH libraries.
        p.c.set_array(&c_after_long_exec);
        p.c.peo_times(3);
        p.r.peo_times(3);
        assert_arrays_eq(
            &format!("row33 seed {seed}: array after long_exec + 3x peo"),
            p.c.array(),
            p.r.array(),
        );
        assert_eq!(p.c.xor(), p.r.xor(), "row33 seed {seed}: XOR differs");
    }
}

// ---------------------------------------------------------------------------
// Live layer: both `.so`s driven through the full 2000-iteration pipeline in one
// process.  ~8 min of C time per seed, hence #[ignore].
// ---------------------------------------------------------------------------

/// Rows 20/22: live C-`.so`-vs-Rust-`.so`, comparing `printf` bytes AND the full
/// 1 MiB exported `array`.
#[test]
#[ignore = "runs the real 2000-iteration C pipeline (~8 min per seed)"]
fn row_live_full_pipeline_diff() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let p = load_pair();
    for seed in seeds_from_env("7") {
        let cout = capture_stdout(&format!("liveC{seed}"), || p.c.long_exec(seed));
        let carr = p.c.array().to_vec();
        let rout = capture_stdout(&format!("liveR{seed}"), || p.r.long_exec(seed));
        assert_eq!(
            String::from_utf8_lossy(&cout),
            String::from_utf8_lossy(&rout),
            "seed {seed}: stdout differs"
        );
        assert_arrays_eq(&format!("seed {seed}: array after long_exec"), &carr, p.r.array());
        eprintln!(
            "live seed {seed}: stdout {:?} and all 1048576 array bytes identical",
            String::from_utf8_lossy(&cout).trim_end()
        );
    }
}

/// Rows 31-32 live: `long_exec` twice / in sequence, in one instance of each library.
#[test]
#[ignore = "runs the real 2000-iteration C pipeline (~8 min per call)"]
fn row_live_ordering_and_idempotence() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let p = load_pair();
    let script = seeds_from_env("7,255,7");
    let mut cs = Vec::new();
    let mut rs = Vec::new();
    for &s in &script {
        cs.push(capture_stdout(&format!("seqC{s}"), || p.c.long_exec(s)));
    }
    for &s in &script {
        rs.push(capture_stdout(&format!("seqR{s}"), || p.r.long_exec(s)));
    }
    for i in 0..script.len() {
        assert_eq!(
            String::from_utf8_lossy(&cs[i]),
            String::from_utf8_lossy(&rs[i]),
            "sequence position {i} (seed {}): stdout differs",
            script[i]
        );
    }
}

/// Row 33 live: `long_exec` then `perform_expensive_operations` on the residue.
#[test]
#[ignore = "runs the real 2000-iteration C pipeline (~8 min per seed)"]
fn row33_live_mixed_entry_points() {
    let _g = common::GLOBAL_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let p = load_pair();
    for seed in seeds_from_env("7") {
        let _ = capture_stdout(&format!("mixC{seed}"), || p.c.long_exec(seed));
        let _ = capture_stdout(&format!("mixR{seed}"), || p.r.long_exec(seed));
        assert_arrays_eq(
            &format!("row33 live seed {seed}: after long_exec"),
            p.c.array(),
            p.r.array(),
        );
        p.c.peo_times(5);
        p.r.peo_times(5);
        assert_arrays_eq(
            &format!("row33 live seed {seed}: after long_exec + 5x peo"),
            p.c.array(),
            p.r.array(),
        );
    }
}

/// Row 35: the project builds no binary/executable target, so there is no
/// binary-stdout comparison to make.  Asserted rather than assumed.
#[test]
fn row35_project_has_no_binary_target() {
    let crate_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let cargo = std::fs::read_to_string(crate_dir.join("Cargo.toml")).unwrap();
    assert!(
        cargo.contains("crate-type = [\"cdylib\"]"),
        "Cargo.toml no longer declares a cdylib-only library"
    );
    assert!(
        !cargo.contains("[[bin]]"),
        "Cargo.toml now declares a binary target -- add a C-vs-Rust stdout \
         comparison for it (CONFIGS.md row 35)"
    );
    assert!(
        !crate_dir.join("src/main.rs").exists(),
        "src/main.rs appeared -- add a binary stdout comparison (CONFIGS.md row 35)"
    );
    let cmake = std::fs::read_to_string(crate_dir.parent().unwrap().join("c_src/CMakeLists.txt"))
        .unwrap();
    assert!(
        !cmake.contains("add_executable"),
        "c_src now builds an executable -- add a binary stdout comparison"
    );
    assert!(cmake.contains("add_library(long SHARED"));
}
